  flex: 1; min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-0_5) var(--space-3);
  appearance: none; border: 0; margin: 0; padding: var(--ld-row-pad) 0; background: none; font: inherit; color: inherit; text-align: left; text-decoration: none;
  -webkit-tap-highlight-color: transparent;
}
.ld-row-target { cursor: pointer; }
/* The whole row is the target of its link or button, and trailing controls sit above it. */
.ld-row-target::after { content: ""; position: absolute; inset: 0; }
.ld-row:has(.ld-row-target:active) { background-image: linear-gradient(var(--fill-control), var(--fill-control)); }
/* The ring sits inside the row, which clips it, so the target reaches past its content to keep the ring clear of it. */
.ld-row-primary.ld-row-target { margin-inline: calc(-1 * var(--space-2)); padding-inline: var(--space-2); }
.ld-row-target:focus-visible { outline-offset: calc(-1 * var(--stroke-ring)); border-radius: var(--radius-xs); }
.ld-row-trailing, .ld-row-more { position: relative; z-index: 2; }
/* Off the baseline, so a Switch is centered in its row and its press area stays inside a 44px row. */
.ld-row-trailing .ld-switch { vertical-align: top; }
.ld-row-leading { flex: none; display: flex; width: var(--size-leading); height: var(--size-leading); margin-block: calc(-1 * var(--ld-row-pad)); align-items: center; justify-content: center; }
/* Beside a leading slot, a value on a line of its own starts under the title: the slot hangs into an inset as wide as
   itself and its gap. */
.ld-row-primary:has(> .ld-row-leading ~ .ld-row-value) { --ld-row-hang: calc(var(--size-leading) + var(--space-3)); padding-inline-start: var(--ld-row-hang); }
