.ld-row-primary:has(> .ld-row-leading ~ .ld-row-value) > .ld-row-leading { margin-inline-start: calc(-1 * var(--ld-row-hang)); }
/* Beside a value, the text keeps room for the title's longest word, and the value moves to the next line when both don't
   fit. Only a word too long for its line breaks. */
.ld-row-main { flex: 1; min-width: 0; display: grid; gap: 1px; overflow-wrap: break-word; }
.ld-row-main:not(:last-child) { display: flex; flex-direction: column; min-width: auto; max-width: 100%; }
.ld-row-main:not(:last-child) > .ld-row-subtitle { contain: inline-size; }
.ld-row-main:last-child { grid-template-columns: minmax(0, 1fr); }
.ld-row-title { font-size: var(--text-body-size); line-height: var(--text-body-line-height); }
.ld-row-subtitle { font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); color: var(--muted-foreground); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* A query's `em` is the browser's text size. Where enlarged text leaves the window under `20em` of it, a subtitle wraps
   so none of it is lost. At the default size, no window 320px or wider matches. */
@media (width < 20em) { .ld-row-subtitle { white-space: normal; } }
/* `subtitleLines`: 2 clamps the subtitle to two lines, and `all` shows every line. */
.ld-row-subtitle[data-lines] { white-space: normal; }
.ld-row-subtitle[data-lines="2"] { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; }
/* Under `20em` of enlarged text, a clamped subtitle shows every line, as a one-line one does. */
@media (width < 20em) { .ld-row-subtitle[data-lines="2"] { display: block; -webkit-line-clamp: none; line-clamp: none; } }
.ld-row-target[aria-current="page"] { font-weight: var(--weight-semibold); }
.ld-row:has(.ld-row-target[aria-current="page"]) { background-image: linear-gradient(var(--fill-control), var(--fill-control)); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-row:has(.ld-row-target[aria-current="page"]) { box-shadow: inset 0 0 0 1px var(--input); }
}
/* Beside the text a value is as wide as its words, and on a line of its own it wraps. */
.ld-row-value {
  min-width: 0; font-size: var(--text-body-size); line-height: var(--text-body-line-height);
  color: var(--muted-foreground); overflow-wrap: break-word;
}
/* StatusText: a status word colored by its tone, at the size of the text around it. */
.ld-status { display: inline-flex; align-items: center; gap: var(--space-1_5); margin: 0; font-weight: var(--weight-semibold); }
.ld-status-dot { flex: none; width: var(--size-status-dot); height: var(--size-status-dot); border-radius: 999px; background: currentColor; }
.ld-status-neutral { color: var(--muted-foreground); }
.ld-status-positive { color: var(--success); }
.ld-status-caution { color: var(--warning); }
.ld-status-critical { color: var(--destructive); }
.ld-row-chevron { flex: none; width: auto; height: var(--size-chevron); color: var(--muted-foreground); pointer-events: none; }
.ld-row-target[aria-expanded] ~ .ld-row-chevron { transition: transform var(--ld-dur) var(--ld-spring); }
.ld-row-target[aria-expanded="true"] ~ .ld-row-chevron { transform: rotate(90deg); }
/* `details`: the row and its swipe actions share a box, and the opened content sits under the row in the same `<li>`. */
.ld-row-slide { position: relative; overflow: hidden; }
.ld-row-details-body { padding: 0 var(--space-4) var(--space-3); }
.ld-tile { width: var(--size-leading); height: var(--size-leading); border-radius: var(--radius-xs); display: flex; align-items: center; justify-content: center; background: var(--primary); color: var(--primary-foreground); }
.ld-tile svg { width: calc(var(--size-leading) - var(--space-3)); height: calc(var(--size-leading) - var(--space-3)); }
/* The ••• glyph lines up with the row's inset, and its round button reaches past it. */
.ld-row-more {
  appearance: none; border: 0; margin: 0 calc((var(--size-icon) - var(--size-row-button)) / 2) 0 0; padding: 0; flex: none;
  width: var(--size-row-button); height: var(--size-row-button);
  display: inline-flex; align-items: center; justify-content: center; border-radius: var(--radius-capsule);
  background: transparent; color: var(--muted-foreground); cursor: pointer; opacity: 0;
  transition: opacity var(--ld-dur) var(--ld-ease), background-color var(--ld-dur) var(--ld-ease);
}
.ld-row-wrap:hover .ld-row-more, .ld-row-wrap:focus-within .ld-row-more, .ld-row-more[data-popup-open] { opacity: 1; }
.ld-row-more:hover, .ld-row-more[data-popup-open] { background: var(--accent); }
.ld-row-more svg, .ld-table-more svg { width: var(--size-icon); height: var(--size-icon); }
/* Wherever a finger can be used, the ••• is always shown, as the visible twin of the swipe: touch screens, and
   laptops with a touch screen, whose main pointer still hovers. */
@media (hover: none), (any-pointer: coarse) { .ld-row-more { opacity: 1; } }
/* Where a finger can be used, the ••• answers a press over `--size-hit-min` around its center, whatever its drawn size. */
