  .ld-row-more::after { content: ""; position: absolute; inset: min(0px, calc((var(--size-row-button) - var(--size-hit-min)) / 2)); }
}
.ld-row-actions { position: absolute; top: 0; right: 0; bottom: 0; display: flex; width: max-content; max-width: 100%; visibility: hidden; transition: visibility 0s linear var(--ld-dur); }
.ld-row-revealed .ld-row-actions { visibility: visible; transition: none; }
/* An action is at least a hit target with the row's inset on each side (76px) and as wide as its longest word, and a
   longer label wraps between words. The actions are never wider than the row, and the row slides by their measured
   width. */
.ld-row-action {
  appearance: none; border: 0; margin: 0; flex: none; width: min-content; min-width: calc(var(--size-hit-min) + 2 * var(--space-4));
  padding: 0 var(--space-2); font: inherit; font-family: var(--font-sans);
  font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); font-weight: var(--weight-semibold); cursor: pointer;
  background: var(--primary); color: var(--primary-foreground);
}
/* When the actions at the current text size don't fit the row, across or down, the component sets `data-fit="tight"`:
   their labels and lines grow no larger than `--size-row-action-max` and `--size-row-action-line-max` (15px and 20px,
   the default size), where three actions fit a 288px row. If that doesn't fit either, `"menu"` hides them, the row
   doesn't open and the ••• menu lists every action. */
.ld-row-actions[data-fit="tight"] .ld-row-action { font-size: min(var(--text-subheadline-size), var(--size-row-action-max)); line-height: min(var(--text-subheadline-line-height), var(--size-row-action-line-max)); }
.ld-row-actions[data-fit="menu"] { display: none; }
.ld-row-action-neutral { background: var(--preset-graphite); }
.ld-row-action-critical { background: var(--destructive); color: var(--destructive-foreground); }
.ld-row-action:focus-visible { outline-color: currentColor; outline-offset: calc(-2 * var(--stroke-ring)); }

/* CodeBlock — `<figure>`, an optional `<figcaption>` and a `<pre><code>` that scrolls once it outgrows its box */
.ld-code { margin: 0; min-width: 0; font-family: var(--font-sans); }
.ld-code-title { margin-bottom: var(--space-1_5); padding: 0 var(--space-1); font-size: var(--text-footnote-size); line-height: var(--text-footnote-line-height); color: var(--muted-foreground); }
.ld-code-pre {
  margin: 0; padding: var(--space-3) var(--space-4); box-sizing: border-box; overflow: auto; overscroll-behavior: contain;
  max-height: var(--ld-code-max-height, var(--layout-code-max-height));
  border-radius: var(--radius-md); background: var(--muted); color: var(--foreground);
  font-family: var(--font-mono); font-size: var(--text-code-size); line-height: var(--text-code-line-height);
}
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-code-pre { box-shadow: inset 0 0 0 1px var(--input); }
}
.ld-code-pre:focus-visible { outline: var(--stroke-ring) solid var(--ring); outline-offset: calc(-1 * var(--stroke-ring)); }
.ld-code-wrap .ld-code-pre { white-space: pre-wrap; overflow-wrap: anywhere; }
/* ANSI colors, as `ANSI_TOKENS` maps them. A bright color shows as its plain one. */
.ld-ansi-black, .ld-ansi-dim { color: var(--muted-foreground); }
.ld-ansi-red { color: var(--destructive); }
.ld-ansi-green { color: var(--success); }
.ld-ansi-yellow { color: var(--warning); }
.ld-ansi-blue { color: var(--preset-blue); }
.ld-ansi-magenta { color: var(--preset-pink); }
.ld-ansi-cyan { color: var(--preset-teal); }
.ld-ansi-white { color: var(--foreground); }
.ld-ansi-bold { font-weight: var(--weight-semibold); }
.ld-ansi-italic { font-style: italic; }
.ld-ansi-underline { text-decoration: underline; }
@media print { .ld-code-pre { max-height: none; overflow: visible; white-space: pre-wrap; overflow-wrap: anywhere; } }

/* AlertDialog — Base UI AlertDialog: a scrim, and a `role="alertdialog"` box centered in the window */
.ld-dialog-backdrop { position: fixed; inset: 0; z-index: var(--z-dialog); background: var(--scrim); transition: opacity var(--ld-dur) var(--ld-ease); }
.ld-dialog-backdrop[data-starting-style], .ld-dialog-backdrop[data-ending-style] { opacity: 0; }
.ld-dialog-viewport { position: fixed; inset: 0; z-index: var(--z-dialog); display: grid; place-items: center; padding: var(--space-4); overflow-y: auto; }
.ld-dialog {
  box-sizing: border-box; width: 100%; max-width: var(--layout-dialog-max-width); padding: var(--space-5);
  border-radius: var(--radius-lg); background: var(--popover); color: var(--popover-foreground); font-family: var(--font-sans);
  box-shadow: 0 0 0 0.5px var(--glass-stroke), var(--shadow-float); outline: 0;
  transition: transform var(--ld-dur) var(--ld-spring), opacity var(--ld-dur) var(--ld-ease);
}
.ld-dialog[data-starting-style], .ld-dialog[data-ending-style] { opacity: 0; transform: scale(var(--scale-pressed)); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-dialog { box-shadow: 0 0 0 1px var(--input); }
}
.ld-dialog-title { margin: 0; font-size: var(--text-headline-size); line-height: var(--text-headline-line-height); font-weight: var(--text-headline-weight); overflow-wrap: break-word; }
.ld-dialog-description { margin: var(--space-2) 0 0; font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); color: var(--muted-foreground); overflow-wrap: break-word; }
/* Cancel then confirm, at the end of the row; a label too long for both to share it gives each a row, confirm on top. */
.ld-dialog-actions { display: flex; flex-wrap: wrap-reverse; justify-content: flex-end; gap: var(--space-2); margin-top: var(--space-5); }
.ld-dialog-actions > .ld-btn { flex: 1 1 auto; }

/* Menu — Base UI Menu (ListRow ••• actions) */
.ld-menu-positioner { z-index: var(--z-menu); outline: 0; }
.ld-menu {
  min-width: var(--size-menu-min-width); padding: var(--space-1_5); box-sizing: border-box; border-radius: var(--radius-md);
  background: var(--popover); color: var(--popover-foreground); font-family: var(--font-sans);
  box-shadow: 0 0 0 0.5px var(--glass-stroke), var(--shadow-float); outline: 0;
  transform-origin: var(--transform-origin);
  transition: transform var(--ld-dur) var(--ld-spring), opacity var(--ld-dur) var(--ld-ease);
}
.ld-menu[data-starting-style], .ld-menu[data-ending-style] { opacity: 0; transform: scale(var(--scale-pressed)); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-menu { box-shadow: 0 0 0 1px var(--input); }
}
.ld-menu-item {
  display: flex; align-items: center; min-height: var(--size-control-md); padding: 0 var(--space-3);
  border-radius: var(--radius-xs); font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); cursor: default; outline: 0; user-select: none;
}
.ld-menu-item[data-highlighted] { background: var(--accent); color: var(--accent-foreground); }
.ld-menu-item-critical { color: var(--destructive); }
.ld-menu-item-critical[data-highlighted] { color: var(--ld-destructive-on-tint); }

/* Disclosure — Base UI Collapsible: a `<section>`, `heading > <button aria-expanded>` and a `hidden="until-found"` panel */
.ld-disc { background: var(--card); color: var(--card-foreground); border-radius: var(--radius-lg); font-family: var(--font-sans); box-shadow: var(--look-surface-edge); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-disc { box-shadow: 0 0 0 1px var(--input); }
}
.ld-disc-plain { background: transparent; border-radius: 0; box-shadow: none; }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-disc-plain { background: transparent; border-radius: 0; box-shadow: none; }
}
.ld-disc-heading { margin: 0; font: inherit; border-radius: inherit; }
.ld-disc-head {
  appearance: none; border: 0; margin: 0; background: transparent; font: inherit; color: inherit; text-align: left;
  display: flex; align-items: center; gap: var(--space-3); width: 100%; min-height: var(--size-hit-min);
