.ld-disc-text { flex: 1; min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-0_5); overflow-wrap: break-word; }
.ld-disc-title { font-size: var(--text-headline-size); line-height: var(--text-headline-line-height); font-weight: var(--text-headline-weight); }
.ld-disc-summary { font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); color: var(--muted-foreground); }
.ld-disc-meta { font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); color: var(--muted-foreground); white-space: nowrap; }
/* Where enlarged text leaves the window under `20em` of it, the meta moves under the title, which keeps its words whole. */
@media (width < 20em) {
  .ld-disc-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: var(--space-0_5) var(--space-3); }
  .ld-disc-meta { grid-row: 2; grid-column: 1; }
  .ld-disc-chevron { grid-row: 1 / span 2; grid-column: 2; }
}
.ld-disc-chevron {
  flex: none; width: auto; height: var(--size-chevron); color: var(--muted-foreground); opacity: var(--opacity-resting);
  transition: transform var(--ld-dur) var(--ld-spring), opacity var(--ld-dur) var(--ld-ease);
}
.ld-disc-head:hover .ld-disc-chevron, .ld-disc-head:focus-visible .ld-disc-chevron { opacity: 1; }
.ld-disc-head[data-panel-open] .ld-disc-chevron { transform: rotate(90deg); }
.ld-disc-panel {
  height: var(--collapsible-panel-height); overflow: hidden; display: flex; flex-direction: column; justify-content: end;
  transition: height var(--ld-dur) var(--ld-ease);
}
.ld-disc-panel[hidden]:not([hidden="until-found"]) { display: none; }
.ld-disc-panel[data-starting-style], .ld-disc-panel[data-ending-style] { height: 0; }
.ld-disc-body { padding: 0 var(--space-4) var(--space-4); }
.ld-disc + .ld-disc { margin-top: var(--space-2); }
.ld-disc-plain + .ld-disc-plain { margin-top: 0; border-top: var(--look-hairline) solid var(--border); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-disc-plain + .ld-disc-plain { border-top-width: 1px; }
}
.ld-disc .ld-disc { background: var(--muted); }
/* Concentric: a list inside a Disclosure sits `--space-2` from the edge, so `--radius-lg` − `--space-2` = `--radius-md`. */
.ld-disc-body > .ld-list:only-child { margin: 0 calc(-1 * var(--space-2)) calc(-1 * var(--space-2)); }
.ld-disc .ld-list-body { background: var(--muted); border-radius: var(--radius-md); }
.ld-disc .ld-list-body .ld-row { background: var(--muted); }

/* GlassBar — `<nav><ul>` of links with `aria-current`. GlassToolbar — Base UI Toolbar. */
.ld-bar {
  display: inline-flex; align-items: center; gap: var(--space-0_5); padding: var(--space-1); border-radius: var(--radius-capsule);
  font-family: var(--font-sans); color: var(--foreground); box-sizing: border-box;
}
.ld-bar-bottom, .ld-bar-top { position: fixed; left: 50%; transform: translateX(-50%); z-index: var(--z-glass-bar); }
.ld-bar-bottom { bottom: max(var(--space-4), env(safe-area-inset-bottom)); }
.ld-bar-top { top: max(var(--space-4), env(safe-area-inset-top)); }
.ld-bar-list { display: flex; gap: var(--space-0_5); min-width: 0; list-style: none; margin: 0; padding: 0; }
/* Each item is a flex box, so it's as tall as its link. A line box would add the page's text height above it. */
.ld-bar-list > li { display: flex; min-width: 0; }
.ld-bar-item {
  appearance: none; border: 0; margin: 0; background: transparent; font: inherit; color: var(--foreground); text-decoration: none;
  display: inline-flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-0_5); box-sizing: border-box;
  min-width: var(--size-tab-min-width); min-height: var(--size-hit-min); padding: var(--space-1) var(--space-3); border-radius: var(--radius-capsule);
  /* A label and its line grow no larger than `--size-bar-label-max` and `--size-bar-label-line-max` (11px and 13px, the
     default size), so five places still fit across a phone at larger text sizes. */
  font-size: min(var(--text-caption-2-size), var(--size-bar-label-max)); line-height: min(var(--text-caption-2-line-height), var(--size-bar-label-line-max));
  font-weight: var(--text-caption-2-weight); cursor: pointer;
  transition: background-color var(--ld-dur) var(--ld-ease), color var(--ld-dur) var(--ld-ease);
}
@media (width <= 26.25em) {
  .ld-bar-list:has(> :nth-child(5)) .ld-bar-item { min-width: 0; padding-inline: var(--space-1); }
}
.ld-bar-icon { display: flex; }
.ld-bar-item svg { width: var(--size-icon-lg); height: var(--size-icon-lg); }
.ld-bar-item[aria-current="page"] { background: var(--card); color: var(--primary); font-weight: var(--weight-semibold); box-shadow: var(--shadow-raised); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-bar-item[aria-current="page"] { box-shadow: inset 0 0 0 1px var(--input); }
}
.ld-bar-tool {
  appearance: none; border: 0; margin: 0; background: transparent; font: inherit; color: var(--foreground);
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-1);
  min-width: var(--size-hit-min); min-height: var(--size-hit-min); padding: 0 var(--space-3);
  font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); font-weight: var(--weight-medium); cursor: pointer;
  /* A one-line tool is a capsule. A wrapped label keeps one line's curve, concentric with the toolbar's ends below. */
  border-radius: min(var(--radius-capsule), calc(max(var(--size-hit-min), var(--text-subheadline-line-height)) / 2));
}
/* GlassToolbar wraps its parts when they don't fit on one line. One line is a capsule; more keep its ends' curve. */
.ld-bar-tools {
  flex-wrap: wrap; justify-content: center;
  border-radius: calc(max(var(--size-hit-min), var(--text-subheadline-line-height)) / 2 + var(--space-1));
}
.ld-bar-tool-icon { padding: 0; }
.ld-bar-tool svg { width: var(--size-icon); height: var(--size-icon); }
.ld-bar-tool:hover, .ld-bar-tool[data-pressed] { background: var(--fill-control); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-bar-tool[data-pressed] { box-shadow: inset 0 0 0 1px var(--input); }
}
.ld-bar-tool[data-disabled] { color: var(--foreground-disabled); cursor: default; }
.ld-bar-sep { width: 0.5px; align-self: stretch; margin: var(--space-2) var(--space-0_5); background: var(--border); }

/* Row-action extras (ListRow and DataTable): disabled actions stay listed, with their reason */
.ld-row-action:disabled { background: var(--fill-control); color: var(--foreground-disabled); cursor: default; }
.ld-menu-item-reason { flex-direction: column; align-items: flex-start; justify-content: center; gap: var(--space-0_5); padding-top: var(--space-1_5); padding-bottom: var(--space-1_5); }
.ld-menu-item[data-disabled] { color: var(--muted-foreground); cursor: default; }
