/* Hit size for dense controls (table rows, checkboxes), read from the density tokens: 44px in regular density
   (`--size-control-md` 36px + `--space-2`), less in compact and at least 24px (WCAG 2.5.8). */
:root, [data-theme], .ld-theme {
  --ld-table-hit: max(var(--size-hit-absolute-min), min(var(--size-hit-min), calc(var(--size-control-md) + var(--space-2))));
