/* An error under a Checkbox's label starts under the box, which sits centered in its hit area. */
.ld-field:has(> .ld-checkbox-field) > .ld-field-hint { padding-inline-start: calc((var(--ld-table-hit) - var(--size-icon)) / 2); }
.ld-checkbox-input { position: absolute; inset: 0; z-index: 1; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.ld-checkbox-input:disabled { cursor: default; }
.ld-checkbox-box {
  display: flex; align-items: center; justify-content: center; width: var(--size-icon); height: var(--size-icon); box-sizing: border-box;
  border: var(--stroke-control) solid var(--muted-foreground); border-radius: var(--radius-xs); background: var(--card); color: var(--primary-foreground);
  transition: background-color var(--ld-dur-quick) var(--ld-ease), border-color var(--ld-dur-quick) var(--ld-ease);
