.ld-checkbox-input:checked + .ld-checkbox-box, .ld-checkbox-input:indeterminate + .ld-checkbox-box { background: var(--primary); border-color: var(--primary); }
.ld-checkbox-input:checked:not(:indeterminate) + .ld-checkbox-box::after {
  display: block; width: 6px; height: 11px; margin-top: -2px; border-width: 0 2px 2px 0; border-radius: 0 0 1px 0; transform: rotate(45deg);
}
.ld-checkbox-input:indeterminate + .ld-checkbox-box::after { display: block; width: 10px; height: 0; border-top-width: 2px; border-radius: 1px; }
.ld-checkbox-input:focus-visible + .ld-checkbox-box { outline: var(--stroke-ring) solid var(--ring); outline-offset: var(--stroke-ring-offset); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-checkbox-box { border-width: var(--stroke-ring); border-color: var(--foreground); }
}
.ld-checkbox-input:disabled + .ld-checkbox-box { background: var(--fill-control); border-color: var(--foreground-disabled); color: var(--foreground-disabled); }
@media (forced-colors: active) {
  .ld-checkbox-box { border-color: CanvasText; }
  .ld-checkbox-input:checked + .ld-checkbox-box, .ld-checkbox-input:indeterminate + .ld-checkbox-box { forced-color-adjust: none; background: Highlight; border-color: Highlight; color: HighlightText; }
}

/* Table — a real `<table>`: sticky header, fixed layout, tokens for every size.
   While the table fits, its box clips but doesn't scroll, so the header sticks to the page (or whatever scrolls the
   page). Only a table wider than its box gets its own scroll box (`[data-overflow]`): it scrolls sideways, and down
   within a max height so its header can stick inside it. */
.ld-table-scroll {
  /* `isolation`: the table's own z-indexes stay inside it, below menus, backdrops and dialogs. */
  /* `min-width`: a clip box is not a scroll container, so as a flex or grid item it would otherwise grow to the table.
     `container-type`: column widths are `calc()`s on the box's width (`100cqi`, as Table.Columns writes them). */
  position: relative; isolation: isolate; overflow: clip; min-width: 0; container-type: inline-size;
  background: var(--card); color: var(--card-foreground); border-radius: var(--radius-lg); font-family: var(--font-sans);
}
.ld-table-scroll[data-overflow] { overflow: auto; max-height: var(--ld-table-max-height, var(--layout-table-max-height)); overscroll-behavior-x: contain; }
.ld-table-scroll[data-overflow] .ld-table-th { top: 0; }
/* Scrolled into view (focus, find-in-page): clear of the sticky header and column, in the box or on the page. */
/* The header is one hit target tall (`.ld-table-th`'s height), and the sticky columns' width comes from Table.Columns. */
.ld-table-body :is(a, button, input) {
  scroll-margin-top: calc(var(--ld-table-hit) + var(--ld-table-sticky-top, 0px)); scroll-margin-left: var(--ld-table-stuck-w, 0px);
