.ld-table[data-collapsed] > :not(caption) { display: none; }
.ld-table[data-collapsed] .ld-table-toggle { border-radius: var(--radius-lg); }
.ld-table-toggle {
  appearance: none; border: 0; margin: 0; background: transparent; font: inherit; color: inherit; text-align: start;
  display: flex; align-items: center; gap: var(--space-3); width: 100%; min-height: var(--size-hit-min);
  padding: var(--space-3) var(--space-4) var(--space-2); cursor: pointer; box-sizing: border-box;
  /* Flush with the box's top edge, so its top corners take the box's radius; collapsed, it's the whole box. */
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  -webkit-tap-highlight-color: transparent;
}
.ld-table-toggle:focus-visible { outline: var(--stroke-ring) solid var(--ring); outline-offset: calc(-1 * var(--stroke-ring)); }
.ld-table-toggle:active { background: var(--fill-control); }
.ld-table-toggle-text { flex: 1; min-width: 0; display: grid; gap: var(--space-0_5); }
.ld-table-toggle-summary { font-size: var(--text-subheadline-size); line-height: var(--text-subheadline-line-height); font-weight: var(--text-subheadline-weight); color: var(--muted-foreground); }
.ld-table-toggle-chevron {
  flex: none; width: auto; height: var(--size-chevron); color: var(--muted-foreground); opacity: var(--opacity-resting); transform: rotate(90deg);
  transition: transform var(--ld-dur-quick) var(--ld-ease), opacity var(--ld-dur-quick) var(--ld-ease);
