.ld-table-toggle:hover .ld-table-toggle-chevron, .ld-table-toggle:focus-visible .ld-table-toggle-chevron { opacity: 1; }
.ld-table-toggle[aria-expanded="false"] .ld-table-toggle-chevron { transform: none; }
.ld-table-th, .ld-table-td, .ld-table-rowheader {
  height: var(--ld-table-hit); padding: 0 var(--space-3); box-sizing: border-box; text-align: start; vertical-align: middle;
  border-bottom: var(--look-hairline) solid var(--border); overflow-wrap: anywhere; background-clip: padding-box;
}
.ld-table-row > :first-child { padding-left: var(--space-4); }
.ld-table-row > :last-child { padding-right: var(--space-4); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-table-th, [data-theme$="-hc"] .ld-table-td, [data-theme$="-hc"] .ld-table-rowheader { border-bottom: 1px solid var(--input); }
}
.ld-table-body .ld-table-row:last-child > * { border-bottom: 0; }
.ld-table-th {
  position: sticky; top: var(--ld-table-sticky-top, 0px); z-index: 3; background: var(--card);
  font-size: var(--text-footnote-size); line-height: var(--text-footnote-line-height); font-weight: var(--weight-semibold); color: var(--muted-foreground); border-bottom-width: 1px;
}
.ld-table-rowheader { font-weight: var(--weight-semibold); }
.ld-table-end { text-align: end; font-variant-numeric: tabular-nums; }
.ld-table-center { text-align: center; }
.ld-table-trunc { display: block; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; overflow-wrap: normal; }
/* Full text while the cell has focus (hover shows it as a title, set when the text is actually clipped). */
.ld-table-rowheader:focus-within .ld-table-trunc, .ld-table-td:focus-within .ld-table-trunc { white-space: normal; overflow-wrap: anywhere; }

/* Selected rows: a tint for people who can see it, and the checkbox carries the state for everyone. */
.ld-table-row[data-selected] > * { background-color: color-mix(in srgb, var(--primary) 10%, var(--card)); }
@container style(--ld-contrast: high) {
  [data-theme$="-hc"] .ld-table-row[data-selected] > :first-child { box-shadow: inset var(--stroke-marker) 0 0 var(--primary); }
}
.ld-table-row[data-selected] .ld-btn-plain:not(.ld-btn-critical) { color: var(--ld-primary-on-tint); }
.ld-table-row:has(.ld-table-link):hover > * { background-image: linear-gradient(var(--fill-control), var(--fill-control)); }

/* Row link: a real `<a>` in the row header, stretched over the `<tr>`. Controls in the row sit above it.
   Stacking, lowest first: the link's `::after` (`auto`) < row controls (1) < sticky body cells (2) < header (3) < the
   header's sticky corner (4). So controls take their own clicks, and scroll under the sticky header and column.
   A row that holds the link is its containing block, so the link covers its own row and no other. */
.ld-table-row:has(.ld-table-link) { position: relative; }
.ld-table-link {
  display: flex; align-items: center; min-height: var(--ld-table-hit); color: inherit; text-decoration: none;
  border-radius: var(--radius-xs); -webkit-tap-highlight-color: transparent;
