.ld-table-rowheader:focus-visible { outline: var(--stroke-ring) solid var(--ring); outline-offset: calc(-1 * var(--stroke-ring)); }
.ld-table-twin { position: absolute; inset: 0; }
/* Every control in a linked row, the caller's own cells' too, sits above the link. `:where` keeps this at zero
   specificity, so a control that positions itself (a checkbox's input) keeps its own `position` and takes the z-index. */
:where(.ld-table-row:has(.ld-table-link) :is(a, button, input, select, textarea, [tabindex]):not(.ld-table-link, .ld-table-twin)),
.ld-table-check .ld-checkbox { position: relative; z-index: 1; }
.ld-table-link .ld-table-trunc { flex: 1; }

/* Control columns */
.ld-table-row > .ld-table-check { padding: 0 var(--space-1); text-align: center; }
.ld-table-row > .ld-table-actions { padding: 0 var(--space-1); text-align: center; }
.ld-table-more {
  appearance: none; border: 0; margin: 0; padding: 0; display: inline-flex; align-items: center; justify-content: center;
  width: var(--ld-table-hit); height: var(--ld-table-hit); border-radius: var(--radius-capsule);
  background: transparent; color: var(--muted-foreground); cursor: pointer; vertical-align: middle;
}
.ld-table-more:hover, .ld-table-more[data-popup-open] { background: var(--accent); color: var(--accent-foreground); }
.ld-table-more:focus-visible { outline: var(--stroke-ring) solid var(--ring); outline-offset: calc(-1 * var(--stroke-ring)); }

/* Sorting: a `<button>` in the header, and `aria-sort` on the sorted `<th>` only */
.ld-table-sort {
  appearance: none; border: 0; background: none; font: inherit; color: inherit; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-1); min-width: var(--ld-table-hit); min-height: var(--ld-table-hit); max-width: 100%; box-sizing: border-box;
  margin: 0 calc(-1 * var(--space-1)); padding: 0 var(--space-1); border-radius: var(--radius-xs); text-align: inherit;
}
