.ld-table-sort:focus-visible { outline: var(--stroke-ring) solid var(--ring); outline-offset: calc(-1 * var(--stroke-ring)); }
.ld-table-sort-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ld-table-sort-icon { flex: none; width: auto; height: var(--size-sort-arrow); opacity: var(--opacity-hint); }
[data-sort-direction] .ld-table-sort { color: var(--foreground); }
[data-sort-direction] .ld-table-sort-icon { opacity: 1; }
[data-sort-direction="ascending"] .ld-table-sort-down, [data-sort-direction="descending"] .ld-table-sort-up { opacity: 0; }

/* Sticky first column (and the checkbox column before it). Opaque, so content never shows through. */
.ld-table-sticky { position: sticky; left: 0; z-index: 2; background-color: var(--card); }
.ld-table-th.ld-table-sticky { z-index: 4; }
.ld-table-check.ld-table-sticky + .ld-table-sticky { left: var(--ld-table-control-w); }
.ld-table-sticky-first .ld-table-row > .ld-table-sticky:not(:has(+ .ld-table-sticky)) { box-shadow: inset -1px 0 0 var(--border); }

/* Skeleton rows keep the layout while the first page loads */
.ld-skel { display: block; width: 72%; max-width: 160px; height: 10px; border-radius: var(--radius-xs); background: var(--fill-control); }
.ld-skel-short { width: 40%; }
.ld-table-skeleton > :nth-child(3n) .ld-skel { width: 48%; }
.ld-table-skeleton > :nth-child(3n + 1) .ld-skel { width: 86%; }
@media (prefers-reduced-motion: no-preference) {
  .ld-skel { animation: ld-skel var(--duration-pulse) var(--ld-ease) infinite alternate; }
  @keyframes ld-skel { from { opacity: 1; } to { opacity: var(--opacity-pulse); } }
}

/* Forced colors (Windows High Contrast and similar): the browser replaces every color with a system color, and
   removes shadows and most backgrounds, so whatever those drew is redrawn here. Rest is a border, on is a `Highlight`
   fill, hover is a `Highlight` border or an underline, disabled is `GrayText` and focus stays an outline. Without
   `forced-color-adjust: none`, text on a fill gets a `Canvas` plate behind it. With it nothing is forced, so every
   color on that element is set here, its focus ring included. The browser forces a ring a control draws on itself to
   `Highlight`, whatever `--ring` holds, and a ring drawn on another element is named `Highlight` here. */
