  .ld-bar-sep { background: CanvasText; }
  .ld-avatar { outline: 1px solid CanvasText; outline-offset: -1px; }
  .ld-skel { background: GrayText; }

  .ld-btn, .ld-bar-tool, .ld-row-more, .ld-row-action { border: 1px solid currentColor; }
