  .ld-btn:is(:disabled, [aria-disabled="true"]), .ld-row-action:disabled, .ld-bar-tool[data-disabled] { color: GrayText; border-color: GrayText; }

  .ld-seg { border: 1px solid ButtonText; }
  .ld-seg-input:checked + .ld-seg-label,
  .ld-bar-item[aria-current="page"],
  .ld-bar-tool[data-pressed],
  .ld-row-more[data-popup-open], .ld-table-more[data-popup-open],
  .ld-menu-item[data-highlighted] {
    forced-color-adjust: none; background: Highlight; color: HighlightText; border-color: Highlight; outline-color: Highlight; box-shadow: none;
  }
  /* The fill's edge has to clear the label: `HighlightText` beyond it would be on `Canvas`. */
