  .ld-switch-knob[data-checked] { background: HighlightText; }
  .ld-switch-disabled { color: GrayText; }
  .ld-switch-track[data-disabled] { outline-color: GrayText; }
  .ld-switch-knob[data-disabled] { background: GrayText; }
  .ld-switch-track[data-checked][data-disabled] { background: GrayText; }
  .ld-switch-knob[data-checked][data-disabled] { background: Canvas; }

  .ld-field-input { border: 1px solid CanvasText; }
  .ld-field-input:focus, .ld-field-input[data-invalid]:focus { outline: var(--stroke-ring) solid Highlight; outline-offset: var(--stroke-ring-offset); }
  .ld-field-input[data-invalid] { border-width: var(--stroke-ring); }
  .ld-field-input:disabled { border-color: GrayText; color: GrayText; }
  .ld-search-icon, .ld-search-clear { color: CanvasText; }
  .ld-search-clear:focus-visible { outline-color: Highlight; }

  .ld-menu-item[data-disabled], .ld-menu-item[data-disabled] .ld-menu-item-hint { color: GrayText; }
  .ld-menu-item[data-highlighted] .ld-menu-item-hint { color: inherit; }
  /* `GrayText` on a `Highlight` fill can't be read, so a disabled item the keyboard reaches is outlined instead. */
