  }

  .ld-row:has(.ld-row-target[aria-current="page"]) { border-inline-start: var(--stroke-marker) solid Highlight; padding-inline-start: calc(var(--space-4) - var(--stroke-marker)); }
  /* An `<svg>` keeps the color it's given here (`preserve-parent-color`), so a chevron takes its parent's forced one. */
