  .ld-disc-head:hover .ld-disc-title, .ld-table-toggle:hover .ld-table-toggle-title, .ld-table-sort:hover .ld-table-sort-label { text-decoration: underline; }
  .ld-table-sort:active { color: Highlight; }

  .ld-checkbox-input:focus-visible + .ld-checkbox-box { outline-color: Highlight; }
  .ld-checkbox-input:disabled + .ld-checkbox-box { border-color: GrayText; }
  .ld-checkbox-input:checked:disabled + .ld-checkbox-box, .ld-checkbox-input:indeterminate:disabled + .ld-checkbox-box { background: GrayText; color: Canvas; }

  .ld-table-row[data-selected] > :first-child { border-inline-start: var(--stroke-marker) solid Highlight; padding-inline-start: calc(var(--space-4) - var(--stroke-marker)); }
  .ld-table-row[data-selected] > .ld-table-check { padding-inline-start: 0; }
